TP.register({id:"lp2-g1",lp:2,grade:"1",mode:"curriculum",checks:1,nextGrade:"2nd grade",build(E){const F=E.F;const ico=(n,px)=>(F.icon||F.pic2)(n,px)||n;const em=(x,y,e,s)=>F.picXY(x,y,e,s)||`<text x="${x}" y="${y}" font-size="${s}" text-anchor="middle" dominant-baseline="central">${e}</text>`;const TRUCK="Gus has a red truck. He fills it with bags. There are ten big bags. Each bag is full of apples. The apples are crisp and red. The truck goes up the hill. Bump! A bag falls off. Apples roll down the path. Gus stops the truck. He runs back. He puts each apple in the bag. Then he sets the bag in the truck. The truck goes on to the shop. Gus will sell the apples. They go in a big bin.";const PLOP="Meg had a big tin tub, and she set it on the grass under the plum tree. Plop! A red plum fell right in. Then, plop, plop, plop! Lots of plums dropped into the tub, one after another. Meg was so pleased. Just then a fat pink pig trotted up the path. It sniffed the tub, grabbed ten juicy plums, and had a big snack. Plum juice ran down its chin. Meg looked at her tub and at the happy pig, and she had to grin.";const HENS="A mother hen sits on her nest. She has five eggs under her warm feathers, and she sits on them for a long time to keep them safe and warm. One day the eggs begin to crack. Out pop the chicks! A new chick is soft and wet, but it dries off fast and turns fluffy. Soon the chicks can peck at the ground and run around the yard behind their mother.";const WORDS=["bud","sap","web","fix","chop","moth","thick","stem","twig","plum","was","mip"];const APPLE="apple",PEAR="pear",PEACH="peach",BEE="bee";const PILE=[[APPLE,PEAR,APPLE,PEACH,APPLE],[PEAR,APPLE,PEAR,PEACH,APPLE],[APPLE,PEAR,PEACH,PEAR,APPLE]];function story(title,text){return`<p class="big" style="text-align:center;margin:0 0 6px">${title}</p><p class="passage">${text}</p>`}const BLK_INK="#6B4A3C";function tens(t,o){return F.blocks(0,t,o)}function pile(rows){const c=76,w=rows[0].length*c+24,h=rows.length*c+24;let s=`<svg viewBox="0 0 ${w} ${h}" width="${w}" role="img" aria-label="A pile of mixed fruit"><rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="none" stroke="var(--line)" stroke-width="3"/>`;rows.forEach((r,ri)=>r.forEach((e,ci)=>{s+=em(12+ci*c+c/2,12+ri*c+c/2,e,50)}));return s+"</svg>"}function plus(){return`<span class="big" style="margin:0 6px" aria-hidden="true">+</span>`}function signFig(){const rows=[[APPLE,"apples"],["egg","eggs"],["peanut","nuts"],["milk","milk"]];return`<div class="figure"><table class="chart" style="font-size:1.7rem"><caption style="font-family:var(--font-display);font-weight:700;font-size:1.5rem;padding-bottom:6px">Farm Stand</caption>${rows.map(r=>`<tr><td style="font-size:2.2rem;padding:4px 18px">${ico(r[0],35)}</td><td style="padding:4px 22px;text-align:left">${r[1]}</td></tr>`).join("")}</table></div>`}function pics(list){return`<div class="figure">${list.map(x=>F.pic(x[0],x[1],"3.6rem")).join("")}</div>`}const TWO=`<ul class="qlist" style="margin-top:14px"><li>Write 2 or 3 sentences.</li></ul>`;const NEWS="Here is the news from Hill Top Orchard. Picking starts on Saturday at nine in the morning. Bring your own basket if you have one. The wagon ride leaves from the big red barn every hour. The cider press runs all day, and a cup of cold cider is free for anyone who picks a full basket.";function unitMeasure(){const cell=58,w=6*cell+200,h=232,ST=`stroke="${BLK_INK}" stroke-width="3"`;const row=(y,n,lab)=>`<rect x="24" y="${y}" width="${n*cell}" height="24" rx="10" fill="#C08A5E" ${ST}/><text x="${24+n*cell+14}" y="${y+12}" font-size="22" font-weight="800" dominant-baseline="central" fill="var(--ink)">${lab}</text>`+Array.from({length:n},(_,i)=>`<rect x="${24+i*cell+3}" y="${y+34}" width="${cell-6}" height="${cell-6}" rx="8" fill="#FBD873" ${ST}/>`).join("");return`<svg viewBox="0 0 ${w} ${h}" width="${w}" role="img" aria-label="Two twigs. Under each twig is a row of same size apple cards."><rect x="4" y="4" width="${w-8}" height="${h-8}" rx="20" fill="var(--surface)" stroke="var(--line)" stroke-width="3"/>`+row(26,6,"twig A")+row(130,4,"twig B")+"</svg>"}const STOPS=[{id:1,title:"Bee Buzz Sounds",short:"Bee Sounds",parts:[{std:["RF.1.2"],n:6,dur:75,dir:"Listen to your teacher. Say the sounds and words out loud.",html:()=>`<div style="text-align:center;margin:8px 0"><img alt="Six pictures: a ladybug on leaves, a garden shed, a jar of strawberry jam, a walnut, a girl picking apples, and a dripping faucet" src="data:image/webp;base64,${window.TP_IMG1.g1sounds}" style="width:680px;max-width:100%;height:auto;border-radius:16px"></div><p class="big" style="text-align:center">Listen. Then say it.</p>`,key:["Blend: /b/ /u/ /g/ (bug)","Blend: /sh/ /e/ /d/ (shed)","What is the first sound in jam? (/j/)","What is the last sound in nut? (/t/)","What is the middle sound in pick? (/i/)","Say all the sounds in drip. (/d/ /r/ /i/ /p/)"],desc:"blending, isolating, and segmenting sounds in spoken words"}]},{id:2,title:"Count the Apples",short:"Count Apples",parts:[{title:"Ladder Count",std:["1.NBT.A.1"],dur:90,dir:"Count and read the numbers out loud.",qs:["Count out loud from 18 to 32.","Count out loud from 67 to 81.","Count out loud from 88 to 103.","Read these numbers out loud: 14, 41, 76, 110."],key:["18, 19, 20 and on to 32. Watch the jumps past 19 and 29","67, 68, 69, 70 and on to 81. Watch the jumps past 69 and 79","88, 89, 90 and on to 99, 100, 101, 102, 103. Watch the jump past 99","Fourteen, forty-one, seventy-six, one hundred ten. Watch for 14 and 41 mixed up"],desc:"counting on from any number and reading numerals to 120"},{title:"Fill the Basket",std:["1.NBT.A.1"],dur:100,dir:"Count the pictures. Write each number on your paper and hold it up.",fig:()=>`<div class="figure" style="align-items:flex-end;gap:40px"><div>${F.objects(APPLE,23,10)}<p class="fig-label">Apples</p></div><div>${F.objects(BEE,15,5)}<p class="fig-label">Bees</p></div></div>`,qs:["Count the apples. Write the number.","Count the bees. Write the number.","Write the number your teacher says.","Write the next number your teacher says.","Write one more number your teacher says."],key:["23 apples (2 rows of ten and 3 more)","15 bees (3 rows of five)","Say: thirty-eight. Writes 38","Say: sixty. Writes 60, not 06 or 16","Say: one hundred five. Writes 105, not 1005"],desc:"counting objects and writing numerals to 120"}]},{id:3,title:"Word Baskets",parts:[{std:["RF.1.3"],kind:"words",words:WORDS,n:12,dur:100,dir:"Read each word out loud. The last one is a silly word. Just sound it out.",key:["Count each word read correctly. mip is a silly word: listen for all three sounds blended.","Watch for: short vowels (bud, sap, web, fix), digraphs (chop, moth, thick), blends (stem, twig, plum), tricky word (was)."],desc:"reading words with short vowels, digraphs, and blends"}]},{id:4,title:"Bee Hops",parts:[{std:["1.OA.C.5"],dur:110,dir:"Listen to each question. Count on or count back. Use your fingers if you want. Say each answer out loud.",qs:["Start at 4. Count on 2. Where do you land?","Start at 8. Count on 3. Where do you land? What adding sentence is that?","Start at 9. Count back 2. Where do you land? What take away sentence is that?","Solve 6 + 4 by counting on. Say the numbers you count.","Spot the mistake. Bee wants to solve 7 + 2. Bee counts: 7, 8. Bee says the answer is 8. What did Bee do wrong?"],key:["Counts 5, 6. Lands on 6","Counts 9, 10, 11. Lands on 11. 8 + 3 = 11","Counts 8, 7. Lands on 7. 9 - 2 = 7","Counts 7, 8, 9, 10. Answer 10. Starts at 6 and does not start over at 1","Bee counted the 7 as a hop. Count on two more: 8, 9. The answer is 9"],desc:"counting on and counting back to add and subtract"}]},{id:5,title:"Truck on the Hill",short:"Truck Read",parts:[{std:["RF.1.4"],kind:"read",n:74,label:"words read correctly",dur:90,dir:"Read the story out loud. Use your best reading voice.",html:()=>`<p style="text-align:center;margin:0 0 8px"><img alt="A red pickup truck with a smiling windshield" src="data:image/webp;base64,${window.TP_IMG1.redtruck}" style="height:120px;width:auto"></p>${story("The Red Truck",TRUCK)}`,key:["74 words, not counting the title. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Note pace, expression, and whether the student rereads to fix a mistake.","Quick check after reading: What fell off the truck? (a bag)"],desc:"a 74-word decodable story read aloud"}]},{id:6,title:"Farm Stand Math",short:"Stand Math",parts:[{std:["1.OA.A.1"],dur:150,dir:"Listen to each story problem. You can draw on your paper. Say your answer.",qon:[()=>`<div style="text-align:center;margin:6px 0 4px"><img alt="A basket with 4 red apples and 3 green apples" src="data:image/webp;base64,${window.TP_IMG1.s6a}" style="width:300px;max-width:100%;height:auto"></div>`,()=>`<div style="text-align:center;margin:6px 0 4px"><img alt="A boy with 6 apples, then 3 more apples, and an empty answer box" src="data:image/webp;base64,${window.TP_IMG1.s6b}" style="width:640px;max-width:100%;height:auto"></div>`,()=>`<div style="text-align:center;margin:6px 0 4px"><img alt="A girl by a flower with 8 bees on it, 5 bees flying away, and an empty answer box" src="data:image/webp;base64,${window.TP_IMG1.s6d}" style="width:560px;max-width:100%;height:auto"></div>`,()=>`<div style="text-align:center;margin:6px 0 4px"><img alt="A girl making jam: 5 jars, plus a question mark, equals 9 jars" src="data:image/webp;base64,${window.TP_IMG1.s6e}" style="width:640px;max-width:100%;height:auto"></div>`,()=>`<div style="text-align:center;margin:6px 0 4px"><img alt="Two cider stands: one stand has 8 jugs and the other has 7 jugs" src="data:image/webp;base64,${window.TP_IMG1.s6c}" style="width:680px;max-width:100%;height:auto"></div>`],qs:["There are 4 red apples and 3 green apples in a basket. How many apples in all?","Kai picks 6 apples. Then he picks 3 more. How many apples does Kai have now?","8 bees sit on a flower. 5 bees fly away. How many bees are left?","Rosa has 5 jars of jam. She makes some more. Now she has 9 jars. How many more jars did she make?","Lee sells 8 jugs of cider. Tam sells 7 jugs. How many jugs do they sell in all? Write a number sentence and hold it up."],key:["7 apples (4 + 3 = 7)","9 apples (6 + 3 = 9)","3 bees (8 - 5 = 3)","4 jars (5 + □ = 9 or 9 - 5 = □)","15 jugs. Writes 8 + 7 = 15"],desc:"addition and subtraction word problems within 20"}]},{id:7,title:"Plop! A Story",short:"Plop!",parts:[{std:["RL.1.1"],dur:110,dir:"Read the story out loud. Then listen to each question and answer out loud.",html:()=>story("Plop!",PLOP),picSup:true,fig:()=>`<div style="text-align:center;margin:8px 0"><img alt="A girl kneels by a metal tub of plums under a plum tree while a pink pig eats a plum" src="data:image/webp;base64,${window.TP_IMG1.plop}" style="width:600px;max-width:100%;height:auto;border-radius:16px"></div>`,qs:["What did Meg set on the grass?","What fell into the tub?","What did the pig do?","Ask me a question about the story."],key:["Her big tin tub","Plums. First one red plum, then lots of plums","It ran up, got ten plums, and had a snack (ate them)","Asks a real question about the story, such as: Why did Meg grin? If stuck, say: Start with who, what, or why."],desc:"asking and answering key detail questions about a story the student read"}]},{id:8,title:"Stack the Crates",short:"Crates",parts:[{std:["1.NBT.C.4"],dur:120,dir:"Add. Say each answer. Show your work for the last one on your paper and hold it up.",qon:[()=>`<div class="figure" style="align-items:center">${tens(2,3)}${plus()}${tens(0,4)}</div>`,()=>`<div class="figure" style="align-items:center">${tens(4,1)}${plus()}${tens(0,5)}</div>`,()=>`<div class="figure" style="align-items:center">${tens(1,5)}${plus()}${tens(1,0)}</div>`,()=>`<div class="figure" style="align-items:center">${tens(3,2)}${plus()}${tens(2,0)}</div>`,()=>`<div class="figure" style="align-items:center">${tens(1,8)}${plus()}${tens(0,5)}</div>`],qs:["Look at the blocks. What is 23 + 4?","41 + 5","15 + 10","32 + 20","18 + 5. Show how you did it."],key:["27. Adds ones to ones: 3 + 4 = 7","46. Keeps 4 tens and adds the ones","25. Adds one more ten","52. Adds tens to tens: 3 tens and 2 tens make 5 tens","23. Makes a new ten (18 + 2 + 3, or a drawing of tens and ones) and tells how"],desc:"adding a two-digit number and a one-digit number or a multiple of 10"}]},{id:9,title:"Farm Stand Writer",short:"Write",parts:[{wk:"opinion",alt:{group:"write",label:"What I Think",icon:"💬",hint:"Pick the best apple treat"},std:["W.1.1"],n:4,label:"checks met",dur:240,dir:"Write on your paper. When you finish, hold it up and read it to your teacher.",html:()=>`<p class="big">Which apple treat is the best? Write what you think. Tell why.</p><div style="text-align:center;margin:14px 0"><img alt="An apple cake slice, a mug of apple cider with a red apple, and a caramel apple" src="data:image/webp;base64,${window.TP_IMG1.treats}" style="width:760px;max-width:100%;height:auto"></div>${TWO}`,key:["Names the topic: apple treats (W.1.1)","States an opinion: tells which treat is best (W.1.1)","Gives a reason for the opinion (W.1.1)","Gives some sense of closure, such as: That is why I like it best (W.1.1)"],desc:"an opinion piece about the best apple treat"},{wk:"facts",alt:{group:"write",label:"Apple Facts",icon:"🍎",hint:"Tell 2 facts about apples"},std:["W.1.2"],n:3,label:"checks met",dur:240,dir:"Write on your paper. When you finish, hold it up and read it to your teacher.",html:()=>`<p class="big">Write about apples. Tell 2 facts you know.</p>${TWO}`,picSup:true,fig:()=>`<div style="text-align:center;margin:8px 0"><img alt="Apple colors: red, green, yellow. Where they grow: on a tree. How they taste: sweet, tart, crisp" src="data:image/webp;base64,${window.TP_IMG1.applefacts}" style="width:620px;max-width:100%;height:auto;border-radius:16px"></div>`,key:["Names the topic: apples (W.1.2)","Gives at least 2 facts about apples, such as color, where they grow, seeds inside, or how we eat them (W.1.2)","Gives some sense of closure, such as: Apples are great (W.1.2)"],desc:"an informative piece with facts about apples"},{wk:"story",alt:{group:"write",label:"Orchard Story",icon:"🌳",hint:"Tell what happens first, next, and last"},std:["W.1.3"],n:4,label:"checks met",dur:240,dir:"Write on your paper. When you finish, hold it up and read it to your teacher.",html:()=>`<p class="big">Write a story about a day at an apple orchard. It can be real or made up. Tell what happens first, next, and last.</p><div class="row center" style="margin-top:20px;gap:18px"><span class="pill" style="font-size:1.4rem">First</span><span class="pill" style="font-size:1.4rem">Next</span><span class="pill" style="font-size:1.4rem">Last</span></div>${TWO}`,key:["Tells 2 or more events in order (W.1.3)","Includes some details about what happened (W.1.3)","Uses time words such as first, next, then, or last (W.1.3)","Gives some sense of closure (W.1.3)"],desc:"a narrative about a day at an apple orchard"}]},{id:10,title:"Sort the Fruit",short:"Fruit Sort",parts:[{std:["1.MD.C.4"],dur:110,dir:"Sort the fruit by kind. Write your numbers on your paper and hold it up. Then answer out loud.",fig:()=>`<div class="figure">${pile(PILE)}</div>`,qs:["Count each kind of fruit: apples, pears, and peaches. Write the 3 numbers.","Which kind has the most? Which kind has the fewest?","How many more apples than pears?","How many pieces of fruit in all?"],key:["Apples 7, pears 5, peaches 3. A tally chart, a list, or a drawing all count","Most: apples. Fewest: peaches","2 more apples (7 - 5 = 2)","15 pieces of fruit (7 + 5 + 3 = 15)"],desc:"sorting, counting, and comparing data in three categories"}]},{id:11,title:"Hen House Facts",short:"Hen Facts",parts:[{std:["RI.1.1"],dur:110,dir:"Read about hens out loud. Then listen to each question and answer out loud.",html:()=>`<div style="text-align:center;margin:6px 0 12px"><img alt="A hen sits on a nest of five eggs. Three chicks hatch from eggs. A wet chick dries and turns fluffy. Five chicks follow the hen across the yard." src="data:image/webp;base64,${window.TP_IMG1.henfacts}" style="width:640px;max-width:100%;height:auto;border-radius:16px"></div>${story("Hens",HENS)}`,qs:["Where does the hen sit?","How many eggs does the hen have?","What can a chick do?","Ask me one question about hens or chicks."],key:["On a nest (on her eggs)","Five eggs","Peck and run","Asks a real question about hens or chicks, such as: What do chicks eat? If stuck, say: Start with what, how, or why."],desc:"asking and answering key detail questions about an informational text the student read"}]},{id:12,title:"Sentence Spy",parts:[{title:"Sentence Spy",std:["RF.1.1"],dur:60,dir:"Look at the sentences. Answer out loud.",html:()=>`<p class="passage" style="text-align:center">The bug is on a stem. Can it hop?</p>`,qs:["Read the first word of the first sentence. What kind of letter does it start with?","What is the mark at the end of the first sentence called?","Look at the last sentence. What is the mark at the end called? What does it tell you?","Spot the mistake. Look at the sentence in the box. What 2 things need to be fixed?"],fig2:()=>`<div class="figure"><p class="passage" style="border:3px dashed var(--line);border-radius:16px;padding:10px 26px;margin:0">the hen sat on a nest</p></div>`,key:["The. It starts with a capital (uppercase) letter","A period","A question mark. It tells you the sentence asks something","It needs a capital T at the start and a period at the end"],desc:"naming the first word, capital letter, and end mark of a sentence"},{title:"Fix It at the Farm",std:["L.1.1"],dur:80,dir:"Listen to your teacher read each one. Say your answer out loud.",qs:["One apple. Two ____.","Which sounds right? The bees buzz. The bees buzzes.","Which sounds right? A apple. An apple.","Meg and Gus pick apples. Say it again with he, she, or they: ____ pick apples.","Add a word that tells what kind: I see a ____ apple.","Is this a whole sentence? The red truck. If not, fix it."],key:["apples (plural noun)","The first one: bees buzz, with no -es on the verb","The second one: an apple","They pick apples","Any describing word that fits, such as red, green, big, shiny, or sweet","No. It does not tell what the truck does or is. Any fix that makes a whole sentence counts, such as: The red truck is big"],desc:"spoken grammar items (plural nouns, matching verbs, a and an, pronouns, describing words, whole sentences)"}]},{id:13,title:"At the Farm Stand",short:"Farm Stand",parts:[{title:"Tell Me About It",std:["SL.1.4"],n:3,label:"checks met",dur:60,dir:"Talk for about one minute. Speak clearly.",html:()=>`<p class="big">Tell me about a food you love to eat.</p><ul class="qlist" style="margin-top:14px"><li>What does it look like?</li><li>How does it taste?</li><li>When do you eat it? How do you feel?</li></ul>`,key:["Names the food and gives 2 or more details about it, such as color, shape, or taste (SL.1.4)","Gives 1 or more details about when or where they eat it, and they stay on this one food (SL.1.4)","Says how the food makes them feel, in at least 1 complete sentence (SL.1.4)"],desc:"describing a favorite food with relevant details"},{title:"Look at the Sign",std:["W.1.8"],n:3,label:"checks met",dur:100,dir:"Look at the sign. Write 1 sentence on your paper and hold it up.",fig:()=>signFig(),html:()=>`<p class="big">What can you get at this farm stand? Tell 2 things from the sign.</p>`,key:["Finds the answer on the sign. Your help is fine: point out the sign and read the question again (W.1.8)","Writes an answer that names 2 things from the sign: apples, eggs, nuts, or milk (W.1.8)","The answer fits the question: it tells what you can get at the stand (W.1.8)"],desc:"using a picture sign to answer a question in writing"}]},{id:14,title:"Orchard News",short:"News",parts:[{std:["SL.1.2"],n:4,dur:50,read:NEWS,dir:"Listen while your teacher reads the orchard news. Then answer out loud.",picSup:true,html:()=>"",fig:()=>`<div style="text-align:center;margin:8px 0"><img alt="A Hill Top Orchard news sign: picking starts Saturday at nine, bring your own basket, the wagon ride leaves from the big red barn every hour, the cider press runs all day, and a cup of cold cider is free for anyone who picks a full basket" src="data:image/webp;base64,${window.TP_IMG1.orchnews}" style="width:720px;max-width:100%;height:auto;border-radius:16px"></div>`,qs:["What time does picking start?","Where does the wagon ride leave from?","What do you have to do to get a free cup of cider?","Ask me a question about the orchard news."],key:["Nine in the morning, on Saturday","The big red barn","Pick a full basket","Asks 1 question that is about the news and starts with a question word, such as: How long is the wagon ride? If stuck, say: Start with what, where, or how.","Read the news once. Read it a second time only if the student asks you to, and write that down."],desc:"answering questions about information heard out loud, and asking a question about it"}]},{id:15,title:"Tens and Ones",short:"Tens",parts:[{title:"What the Digits Mean",std:["1.NBT.B.2"],n:3,dur:45,dir:"Look at the blocks. Answer out loud.",qon:[()=>`<div class="figure" style="align-items:center;margin:6px 0 10px">${tens(4,6)}</div>`],qsup:[null,()=>`<div class="figure" style="align-items:center;margin:6px 0 10px">${tens(4,6)}</div>`,()=>`<div class="figure" style="align-items:center;margin:6px 0 10px">${tens(3,0)}</div>`],qs:["How many tens and how many ones? What number is this?","In that number, what does the 4 stand for?","What about 30? How many tens and how many ones?"],key:["4 tens and 6 ones. The number is 46","4 tens, which is 40. Not just four","3 tens and 0 ones. Each ten is a bundle of ten ones"],desc:"reading the tens digit and the ones digit of a two-digit number"},{title:"Take Away Tens",std:["1.NBT.C.6"],n:3,dur:45,dir:"Subtract. Say each answer out loud.",qsup:[()=>`<div class="figure" style="align-items:center;margin:6px 0 10px">${tens(6,0)}</div>`,()=>`<div class="figure" style="align-items:center;margin:6px 0 10px">${tens(9,0)}</div>`,()=>`<div class="figure" style="align-items:center;margin:6px 0 10px">${tens(7,0)}</div>`],qs:["60 - 20","90 - 40","70 - 70"],key:["40. Six tens take away two tens leaves four tens","50. Nine tens take away four tens leaves five tens","0. Seven tens take away seven tens leaves no tens"],desc:"subtracting a multiple of ten from a multiple of ten"},{title:"Swap and Group",std:["1.OA.B.3"],n:2,dur:45,dir:"Answer out loud. Tell how you know.",html:()=>`<p class="big" style="text-align:center">4 + 9 = 13</p>`,qsup:[()=>`<div class="figure" style="align-items:center;margin:6px 0 10px">${tens(0,9)}${plus()}${tens(0,4)}</div>`,()=>`<div class="figure" style="align-items:center;margin:6px 0 10px">${tens(0,8)}${plus()}${tens(0,2)}${plus()}${tens(0,6)}</div>`],qs:["You know 4 + 9 = 13. So what is 9 + 4? How do you know without counting?","Add 8 + 2 + 6. Which two would you put together first, and why?"],key:["13. The order of the two parts does not change the total, so there is nothing to count again","8 and 2 first, because they make 10. Then 10 + 6 = 16. The answer is 16. Any correct regrouping with a reason counts"],desc:"using the order of addends and grouping addends to add"}]},{id:16,title:"Twigs and Clocks",short:"Measure",parts:[{title:"How Many Cards Long",std:["1.MD.A.2"],n:3,dur:45,dir:"Look at the twigs and the apple cards. Answer out loud.",fig:()=>`<div style="text-align:center;margin:8px 0"><img alt="Twig A is as long as 6 apple cards. Twig B is as long as 4 apple cards." src="data:image/webp;base64,${window.TP_IMG1.twigs}" style="width:720px;max-width:100%;height:auto;border-radius:16px"></div>`,qs:["The apple cards are all the same size. How many cards long is twig A?","How many cards long is twig B?","How much longer is twig A than twig B?"],key:["6 cards long","4 cards long","2 cards longer (6 - 4 = 2)","The cards must be counted with no gaps and no overlaps. If the student counts the lines between cards instead of the cards, note it."],desc:"measuring length as a whole number of same-size units"},{title:"Orchard Clocks",std:["1.MD.B.3"],n:3,dur:45,dir:"Look at the clocks. Say each time out loud. Write the last one on your paper.",fig:()=>`<div class="figure" style="align-items:center;gap:24px">${F.clock(9,0,190)}${F.clock(1,30,190)}${F.digital("4:30")}</div>`,qs:["Picking starts at this time. What time is it?","The wagon ride leaves at this time. What time is it?","The stand closes at the time on the digital clock. Say it, then write it on your paper."],key:["9:00, or nine o'clock","1:30, or half past one. The hour hand sits between 1 and 2, which is the usual place to slip","4:30. Writes 4:30 with the colon. Four thirty or half past four said out loud is correct too"],desc:"telling and writing time to the hour and half hour on analog and digital clocks"}]},{id:17,title:"Equal Shares",short:"Shares",parts:[{std:["1.G.A.3"],n:3,dur:45,dir:"Look at the pie and the crate top. Answer out loud.",fig:()=>`<div style="display:flex;align-items:center;justify-content:center;gap:30px;flex-wrap:wrap;margin:8px 0"><img alt="A pie cut into 2 equal parts. One part is cherry and one part is crust." src="data:image/webp;base64,${window.TP_IMG1.piehalf}" style="height:190px;width:auto;max-width:100%"><img alt="A wooden crate top cut into 4 equal parts" src="data:image/webp;base64,${window.TP_IMG1.crate4}" style="width:380px;max-width:100%;height:auto"></div>`,qsup:[null,null,()=>`<div style="text-align:center;margin:6px 0 10px"><img alt="Two pies. One is cut into 2 equal parts. The other is cut into 4 equal parts." src="data:image/webp;base64,${window.TP_IMG1.pies24}" style="width:520px;max-width:100%;height:auto"></div>`],qs:["The pie is cut into 2 equal parts. What do we call one of those parts?","The crate top is cut into 4 equal parts. What do we call one of those parts?","If you cut the same pie into 4 equal parts instead of 2, would each piece be bigger or smaller?"],key:["A half, or one half. Two halves is also fine as a description of the whole pie","A fourth, or a quarter. One fourth of the crate top","Smaller. More equal shares of the same whole means each share is smaller","The parts have to be equal to be halves or fourths. If the student calls any two pieces halves, say: Are they the same size?"],desc:"naming halves and fourths of a circle and a rectangle, and comparing the size of the shares"}]},{id:18,title:"Copy a Bird's Beak",short:"Copy a Beak",parts:[{std:["1-LS1-1"],n:3,dur:90,dir:"Look at the pictures. Answer the first out loud. Draw the second on your paper and hold it up.",desc:"naming the job an animal body part does, then designing a tool that copies it to solve a human problem",html:()=>`<p class="big">A parrot has a thick beak. It curves down to a point. It hooks over a branch. It pulls the branch close. Then the bird can reach the fruit.</p>
     <div class="figure">${ico("parrot",104)}${ico("apple",96)}</div>
     <p class="big">The best apples are at the top. They are up in the tree. A picker cannot reach that high.</p>`,qs:["How does a curved, hooked beak help a parrot get to fruit it could not otherwise reach?","Draw a picking tool for the top of the tree that copies the parrot's hooked beak.","Tell me which animal part you copied and how the hook on your tool brings an apple down."],key:["It hooks over the branch and pulls it closer, so the fruit comes to the bird. Any answer about hooking and pulling counts.","Any long tool with a hook or curve at the end: a pole with a crook, a bent wire on a stick, a hooked basket on a handle. A straight stick with no hook is partial, so ask what the beak's shape does.","Needs both halves: names the curved hooked beak as the part copied, and says the hook catches the branch or the stem and pulls, so the apple comes down."]}]},{id:19,title:"Hen and Chicks",short:"Hen",parts:[{std:["1-LS1-2"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"finding a pattern in what a parent animal does and what the young do in answer, and saying how it helps the young",read:"Behind the apple barn a hen walks slowly through the grass with six chicks behind her. She scratches at the ground with one foot, then steps back and looks down. Every time she steps back, the chicks run in and peck at the loose dirt where she scratched. The hen makes a low, steady cluck the whole time she walks. When she stops clucking, the chicks stop too and stand close to her feet.",qs:["What do the chicks do every single time the hen steps back from her scratching?","What do the chicks do when the hen stops clucking?","How does the hen's scratching help the chicks get food they could not get on their own?"],key:["They run in and peck at the loose dirt. Every time is what makes it a pattern.","They stop walking and stand close to her feet.","Her foot turns over the dirt and uncovers seeds and bugs that were buried. A small chick cannot scratch that hard, so the parent does the digging."]},{std:["1-LS3-1"],n:3,dur:75,dir:"Look at the two pairs. Answer out loud.",desc:"making observations that young plants and animals are like their parents but not exactly like them",html:()=>`<p class="big">A young apple tree grown from a seed. The grown apple tree it came from. A chick. The hen that is its parent.</p>
     <div class="figure">${ico("sprout",92)}${ico("tree",104)}</div>
     <div class="figure">${ico("chick",92)}${ico("hen",104)}</div>`,qs:["Name one way the young apple tree is like the grown apple tree.","Name one way the young apple tree is not exactly like the grown apple tree.","Six chicks hatched from the same hen. Two are pale yellow and four are brown. Does that fit with young being like their parent but not exactly like it? Say why."],key:["Both have a stem or trunk, green leaves, and roots in the soil. Any likeness counts.","The young one is much shorter, it has a thin stem instead of a thick trunk, it has no apples. Any difference counts.","Yes. They are all chicks of that hen, so they are alike in big ways, but even the ones from the same parent are not the same as each other or exactly the same as her."]}]},{id:20,title:"The Moon Over the Orchard",short:"Sky Patterns",parts:[{std:["1-ESS1-1"],n:4,dur:90,dir:"Look at the moon log. Answer out loud.",desc:"finding a pattern in a log of sky observations and using it to predict what comes next",html:()=>`<p class="big">The orchard keeper looked at the moon on four nights, one week apart each time.</p>
     <table class="bigTable"><tr><th>Night</th><th>What the moon looked like</th></tr>
     <tr><td>first night</td><td>a thin curve</td></tr>
     <tr><td>one week later</td><td>half a circle</td></tr>
     <tr><td>two weeks later</td><td>a full round circle</td></tr>
     <tr><td>three weeks later</td><td>half a circle again</td></tr></table>
     <div class="figure">${ico("moon",88)}${ico("tree",88)}${ico("star",88)}</div>`,qs:["What did the moon look like on the first night?","What did it look like two weeks later?","Four weeks after the first night, what do you predict the moon will look like? Say how the log helps you know.","The sun has come up over the far row of trees every morning this week. Where do you predict it will come up tomorrow?"],key:["a thin curve","a full round circle","A thin curve again. The shapes go in a pattern that repeats, so the pattern tells you what comes next.","Over the far row of trees, the same place. It has done the same thing every morning, which is what makes it something you can predict."]},{std:["1-ESS1-2"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"relating the number of hours of daylight to the time of year from observations made across a year",html:()=>`<p class="big">The orchard keeper counted how many hours there was enough daylight to pick.</p>
     <table class="bigTable"><tr><th>Month</th><th>Hours of daylight</th></tr>
     <tr><td>June</td><td>15</td></tr><tr><td>September</td><td>12</td></tr>
     <tr><td>December</td><td>9</td></tr></table>`,qs:["Which month on the chart had the most hours of daylight?","How many fewer hours of daylight did December have than June?","The pickers want a long day of work. Should they pick in June or in December? Use the chart to say why."],key:["June, 15 hours","6 fewer hours. 15 take away 9","June, because June has 15 hours of daylight and December has only 9, so there is more time to work before dark."]}]},{id:21,title:"Sound in the Barn",short:"Sound",parts:[{std:["1-PS4-1"],n:4,dur:90,dir:"If you have string and an empty box, try the first part first. Either way, answer out loud.",desc:"planning an investigation showing that a shaking material makes sound and that a sound can make a material shake",html:()=>`<p class="big">Stretch a piece of string tight across an empty crate and pluck it once. Watch the string while you listen.</p>
     <div class="figure">${ico("box",96)}${ico("pan",96)}</div>
     <p class="big">Now tape a thin paper strip so it just touches the side of an empty tin pail. Tap the pail hard with a wooden spoon.</p>`,qs:["While you hear the note, what is the string doing?","Press one finger on the string while it is still sounding. What happens to the sound, and why?","When the pail is tapped, what does the paper strip do?","The strip moved even though you never touched it. What does that tell you about what sound can do?"],key:["Shaking back and forth fast. Buzzing, wobbling, vibrating, going blurry, all count.","The sound stops, because the string is no longer shaking. No shaking means no sound.","It buzzes, flutters, or jumps against the side of the pail.","A sound can make something else shake. The tapped pail was shaking, and that shaking passed to the paper strip."]}]},{id:22,title:"In the Cellar",short:"Light",parts:[{std:["1-PS4-2"],n:3,dur:75,dir:"Answer out loud.",desc:"accounting for why an object in darkness can be seen only when light shines on it",html:()=>`<p class="big">The apple cellar is under the barn. It has no window, and the door fits tight.</p>
     <div class="figure">${ico("apple",96)}${ico("torch",96)}</div>`,qs:["A crate of red apples is in the cellar with the door shut. Can you see them? Say why or why not.","What has to happen before you can see the apples down there?","Someone says shiny things can be seen in the dark all by themselves. Is a shiny apple in a pitch dark room easier to see? Say what a shiny thing really needs."],key:["No. No light gets into the cellar, and nothing can be seen unless light shines on it and comes back to your eyes.","Light has to get in: a lamp, a flashlight, a candle in a holder, or the door opened to let daylight in.","No. A shiny thing is only shiny because it bounces light back. With no light at all there is nothing for it to bounce, so it cannot be seen either."]},{std:["1-PS4-3"],n:4,dur:90,dir:"Look at the test results. Answer out loud.",desc:"using test results to tell what happens when different materials are put in the path of a beam of light",html:()=>`<p class="big">In the dark cellar the keeper shone one flashlight beam at four things and wrote down what the beam did.</p>
     <table class="bigTable"><tr><th>What was put in the beam</th><th>What the beam did</th></tr>
     <tr><td>a clean glass jar</td><td>went straight through</td></tr>
     <tr><td>a brown paper bag</td><td>a little came through, dim</td></tr>
     <tr><td>a crate lid made of wood</td><td>stopped, and made a dark shadow</td></tr>
     <tr><td>a shiny metal pail</td><td>bounced off in a new direction</td></tr></table>`,qs:["Which thing let the light go straight through?","Which thing made a dark shadow on the wall behind it?","Put the four in order from the one that let the most light through to the one that let the least.","You want to make the cellar brighter without moving the flashlight. Which of the four would help, and how?"],key:["the clean glass jar","the wooden crate lid","glass jar, then paper bag, then the shiny pail or the wood. Accept glass, paper, wood as the top three in that order. The shiny pail may be placed anywhere, because it sends light sideways rather than through.","the shiny metal pail, because it bounces the beam off into another part of the room instead of letting it stop at one wall."]}]},{id:23,title:"Calling Across the Rows",short:"Signals",parts:[{std:["1-PS4-4"],n:3,dur:90,dir:"Draw your answer on your paper. Then answer out loud.",desc:"designing a device that uses light or sound to send a message over a distance too far to shout",html:()=>`<p class="big">The orchard is twenty long rows wide. A picker at the far end cannot hear anyone shouting from the barn.</p>
     <div class="figure">${ico("tree",88)}${ico("megaphone",88)}${ico("lantern",88)}</div>`,qs:["Draw a device at the barn that tells every picker in every row that the water is ready. It has to use light or sound.","Say out loud what you drew, and say whether it works by light or by sound.","The pickers also need to know when a wagon is coming down a row. How would your device say that message instead, so the two are not mixed up?"],key:["Any device that carries light or sound a long way: a bell on a post, a horn, a whistle, a drum, a bright lamp hoisted on a pole, a mirror catching the sun.","Names it and says which one it uses. Sound for a bell, a horn, a whistle, a drum. Light for a lamp or a mirror.","Needs a second signal that is clearly different: two rings instead of one, a long sound instead of a short one, a different color of light. The idea to listen for is that the two messages must not look or sound the same."]}]},{id:24,title:"Fix the Bruised Apples",short:"Fix It",parts:[{std:["K-2-ETS1-1"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"naming a problem people want to change, asking a question about it, and saying what to observe first",read:"At the end of each row the pickers tip their bags into a wooden crate. The apples drop onto the hard bottom of the crate and land on each other. When the crates reach the stand, a lot of the apples have soft brown bruises on them, and bruised apples cannot be sold.",qs:["What is the problem the orchard wants to change?","Think like a builder. What is one question you would want answered before you fix it?","Name one thing you would count or watch first, before you build anything."],key:["Apples get bruised when they are tipped into the hard crate, and bruised apples cannot be sold.","Any real question: how far do the apples fall, how hard is the bottom, how many go in at once, which apples bruise most. A statement is not a question, so ask once more.","Any real observation: count how many apples in one crate are bruised, measure how far they fall, watch which part of the crate does the bruising."]},{std:["K-2-ETS1-2"],n:3,dur:90,dir:"Draw your answer on your paper and hold it up. Then answer out loud.",desc:"making a simple drawing of a fix and explaining how the shape of the object makes it work",html:()=>`<p class="big">Draw something that gets the apples into the crate without a hard drop.</p>
     <div class="figure">${ico("apple",88)}${ico("box",88)}${ico("leaf",88)}</div>`,qs:["Draw your fix on the crate.","Point to the part that protects the apples and tell me its shape.","Tell me why that shape works better than just telling the pickers to be careful."],key:["Any real fix: a soft pad in the bottom, a cloth lining up the sides, a sloping slide or chute into the crate, a smaller crate so the fall is shorter.","Names a shape: a soft flat pad, a sloping ramp, a curved chute, a deep soft nest.","Because the shape does the work every single time on its own. Being careful depends on a person remembering, and the shape never forgets."]}]},{id:25,title:"Which Liner Worked",short:"Test Data",parts:[{std:["K-2-ETS1-3"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"comparing the data from tests of two objects built to solve the same problem",html:()=>`<p class="big">The orchard tested two crate liners. Each liner got twenty apples tipped into it, and then the bruises were counted.</p>
     <table class="bigTable"><tr><th>Liner</th><th>Bruised apples, out of 20</th></tr>
     <tr><td>a thick straw pad</td><td>2</td></tr>
     <tr><td>a single sheet of paper</td><td>11</td></tr></table>`,qs:["Which liner worked better in the test?","Read me the two numbers from the chart that show it.","Someone says the paper is better because it costs less. Does that make the paper better at stopping bruises? Say why or why not."],key:["the thick straw pad","Only 2 apples out of 20 bruised with the straw pad, and 11 out of 20 bruised with the paper. The numbers have to be in the answer.","No. Costing less is a different thing from working better. The test counted bruises, and the straw pad had far fewer."]}]},{id:26,title:"The Stand Vote",short:"Rights",parts:[{std:["HSS-1.1"],n:4,dur:90,dir:"Listen while your teacher reads. Then answer out loud.",desc:"telling a right from a responsibility and naming the responsibility that goes with taking part in a vote",read:"The farm stand has room for only two kinds of apples on the front table. Everyone who works at the stand got one slip of paper and wrote down the kind they wanted. Then they counted the slips out loud so that everybody could see the count. Red apples got nine slips. Green apples got seven. Yellow apples got four. Red and green went on the table. When every single person votes on the thing itself, that is called direct democracy. A whole town has too many people for that, so the people of a town vote for a few helpers, called a council, and the council makes the rules. That is called representative democracy.",qs:["Everyone got a slip of paper and a say in the choice. Is that a right or a responsibility?","Counting the slips out loud where everyone can see is a job somebody has to do. Is that a right or a responsibility?","A worker who voted for yellow apples is disappointed. What should that worker do now that the count is finished, and why?","Everyone at the stand voted on the apples themselves. In a town, people vote for a council and the council makes the rules. What is each of those two ways called?"],key:["A right. It is something every person at the stand gets.","A responsibility. It is a job that has to be done, and done honestly.","Go along with the count, because that is what everybody agreed the vote would decide. Accept also that the worker can still ask for yellow apples next time.","Everyone voting on the thing itself is direct democracy. Voting for a council that makes the rules is representative democracy. Both names are what is being checked, and the student may also give a plain version, such as everybody votes, or we pick somebody to decide for us. (HSS-1.1)"]}]},{id:27,title:"The Orchard Map",short:"Map Grid",parts:[{std:["HSS-1.2"],n:4,dur:90,dir:"Look at the map grid. Answer out loud.",desc:"giving an exact grid location, describing a relative location, and telling a physical feature from a built one",html:()=>`<p class="big">A map of the orchard, drawn on a grid.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ico("tree",56)}</td><td>${ico("tree",56)}</td><td>${ico("mountain",56)}</td></tr>
     <tr><th>B</th><td></td><td>${ico("cabin",56)}</td><td></td></tr>
     <tr><th>C</th><td>${ico("drop",56)}</td><td></td><td>${ico("bridge",56)}</td></tr></table>
     <p class="big">${ico("tree",48)} apple trees &nbsp; ${ico("mountain",48)} the hill &nbsp; ${ico("cabin",48)} the barn &nbsp; ${ico("drop",48)} the pond &nbsp; ${ico("bridge",48)} the bridge</p>`,qs:["Find the barn. Give its exact spot on the grid, the letter and the number.","Where is the pond compared to the barn? Use a word like above, below, left of, or right of.","Name two things on this map that nature put there.","Name two things on this map that people built."],key:["B2. Both parts are needed.","Below the barn and to the left of it. Any correct position word counts, and down and over counts too.","The apple trees, the hill, or the pond. Accept the trees even though people planted them, as long as the student explains that trees grow.","The barn and the bridge."]},{std:["HSS-1.5"],n:3,dur:75,dir:"Answer out loud about the town you live in.",desc:"naming built features of a familiar place and recognizing that people in one place come from many different places",html:()=>`<p class="big">The people who pick at this orchard come from six different towns, and three of them speak a second language at home.</p>
     <div class="figure">${ico("bus",88)}${ico("cabin",88)}${ico("truck",88)}</div>`,qs:["Name three things people built in the town where you live.","Do all the people who work in one place have to come from the same town? Say how you know from the story above.","A thing a family keeps doing year after year is called a tradition or a custom. Name one tradition or custom a family might keep after moving to a new town, something from the place they came from."],key:["Any three built things: stores, roads, a school, a library, houses, a bridge, a fire station, a park bench.","No. The pickers come from six different towns and some speak a second language at home.","Any real tradition or custom named: cooking a certain food, speaking a language at home, singing a song, a dance, a game, the way a family marks a birthday, the way a family welcomes a visitor. The word tradition or custom used correctly is the part to listen for. (HSS-1.5)"]}]},{id:28,title:"Symbols, Then and Now",short:"Symbols",parts:[{std:["HSS-1.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling what a national symbol and a national tradition are, and why a country keeps them",html:()=>`<p class="big">The Statue of Liberty stands up. She is on an island. A harbor holds the island. New York has the harbor. She holds a torch up high. She has stood there a long time. It has been very long. Many people are arriving by ship. She is the first thing they see.</p>
     <div class="figure">${ico("torchflame",100)}${ico("flag",100)}</div>`,qs:["What does the Statue of Liberty hold up high?","People arriving by ship saw her first. What message do you think a torch held up high was meant to send them?","On one day every year some towns hold a parade down the main street with flags along it. Why would a whole town do the same thing year after year?"],key:["a torch","Welcome, you have arrived, there is light here, this is a free country. Any sensible welcoming meaning counts. This is the question that shows a symbol stands for an idea.","Because doing the same thing together year after year is a tradition, and it reminds people they belong to the same country and the same town."]},{std:["HSS-1.4"],n:4,dur:90,dir:"Look at the chart. Answer out loud.",desc:"comparing everyday life long ago with life today and telling what changed from what stayed the same",html:()=>`<p class="big">Getting apples from the orchard to the market.</p>
     <table class="bigTable"><tr><th></th><th>Long ago</th><th>Today</th></tr>
     <tr><td>how they traveled</td><td>a horse pulled a wooden wagon</td><td>a truck with an engine</td></tr>
     <tr><td>how long it took</td><td>most of a day</td><td>about an hour</td></tr>
     <tr><td>who picked them</td><td>people, by hand</td><td>people, by hand</td></tr></table>
     <div class="figure">${ico("horse",88)}${ico("truck",88)}</div>`,qs:["Long ago, what pulled the apples to the market?","What carries them today?","Point to one row of the chart where things are different now from how they were.","Name one thing in the chart that stayed the same, even after all that time."],key:["a horse pulling a wooden wagon","a truck with an engine","How they traveled changed, or how long it took changed. Either counts.","People still pick the apples by hand. This is the half of the standard that is easy to miss, so it is asked on its own."]}]}];const LEVELUPS={2:{id:"L2",lv:true,title:"Level Up: Skip Count",std:["2.NBT.A.2"],needs:["1.NBT.A.1"],n:3,dir:"Count out loud.",html:()=>`<ol class="qlist"><li>Count by 10s from 60 to 140.</li><li>Count by 5s from 45 to 80.</li><li>Count by 100s from 200 to 700.</li></ol>`,key:["60, 70, 80, 90, 100, 110, 120, 130, 140","45, 50, 55, 60, 65, 70, 75, 80","200, 300, 400, 500, 600, 700"]},3:{id:"L3",lv:true,title:"Level Up: Big Words",std:["RF.2.3"],needs:["RF.1.3"],n:3,dir:"Read each word out loud.",html:()=>`<div style="text-align:center">${["treetop","refill","seedless"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["treetop (two parts, vowel team ee)","refill (prefix re-)","seedless (suffix -less)"]},6:{id:"L6",lv:true,title:"Level Up: Two-Step Problem",std:["2.OA.A.1"],needs:["1.OA.A.1"],n:1,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">A farmer had 40 apples. She picked 25 more. Then she sold 12. How many apples does she have now?</p>`,key:["53 apples (40 + 25 = 65, then 65 - 12 = 53)"]},10:{id:"L10",lv:true,title:"Level Up: Basket Graph",std:["2.MD.D.10"],needs:["1.MD.C.4"],n:2,dir:"Look at the bar graph. Answer out loud.",html:()=>`<div class="figure">${F.barGraph({title:"Baskets of Apples Sold",cats:["Mon","Tue","Wed","Thu"],vals:[6,9,4,7],max:10,step:1})}</div><ol class="qlist"><li>How many baskets were sold on Monday and Tuesday together?</li><li>How many more baskets were sold on Tuesday than on Wednesday?</li></ol>`,key:["15 baskets (6 + 9 = 15)","5 more baskets (9 - 4 = 5)"]}};const PASSAGE_STD=["RL.1.1","RI.1.1","1-LS1-1","1-LS1-2","1-LS3-1","1-ESS1-1","1-ESS1-2","1-PS4-1","1-PS4-2","1-PS4-3","1-PS4-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-1.1","HSS-1.2","HSS-1.3","HSS-1.4","HSS-1.5"];let nlOn={},tfOn={},blk=[0,0],c120On={};function nlHtml(){const marks=Object.keys(nlOn).filter(k=>nlOn[k]).map(Number);return F.numberLine({min:0,max:20,step:1,labelEvery:1,width:680,marks,clickable:true,fluid:true})+`<p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}function blkHtml(){return`<div class="blk-row"><button class="chip" data-b="0" data-d="1">Add a ten</button><button class="chip" data-b="0" data-d="-1">Take a ten</button><button class="chip" data-b="1" data-d="1">Add a one</button><button class="chip" data-b="1" data-d="-1">Take a one</button><button class="chip" data-b="x">Clear</button></div><div class="tool-scroll" style="text-align:center">${blk[0]+blk[1]?tens(blk[0],blk[1]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${blk[0]} tens and ${blk[1]} ones on the mat.</p>`}function c120Html(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${c120On[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}const STARTERS={opinion:["I think ____ is the best.","One reason is ____.","That is why ____."],facts:["Apples are ____.","One fact is ____.","Another fact is ____.","Now you know about ____."],story:["One day, ____.","First, ____.","Next, ____.","Last, ____."]};const SENTSET={"W.1.1":"opinion","W.1.2":"facts","W.1.3":"story","W.1.8":"facts"};const SENTLAB={opinion:"If you are writing what you think:",facts:"If you are writing facts:",story:"If you are telling a story:"};function sentHtml(st){const parts=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const sets=[];parts.forEach(p=>(p.std||[]).forEach(c=>{const k=SENTSET[c];if(k&&STARTERS[k]&&sets.indexOf(k)<0)sets.push(k)}));if(!sets.length){const k=parts[0]&&parts[0].wk;sets.push(STARTERS[k]?k:"opinion")}return sets.map(k=>(sets.length>1?`<p class="small">${SENTLAB[k]}</p>`:"")+`<ul class="starters">${STARTERS[k].map(x=>`<li>${x}</li>`).join("")}</ul>`).join("")}F.clockLab=(h,m)=>{const cx=190,cy=190,R=150,pad=n=>String(n).padStart(2,"0");let s=`<svg viewBox="0 0 380 380" width="360" style="max-width:100%;height:auto" role="img" aria-label="Clock face with the hour hand and the minute hand labeled, showing ${h}:${pad(m)}">`;s+=`<circle cx="${cx}" cy="${cy}" r="${R+8}" fill="#F3DCC4" stroke="var(--fig-ink)" stroke-width="4"/><circle cx="${cx}" cy="${cy}" r="${R}" fill="var(--surface)" stroke="var(--fig-ink)" stroke-width="3"/>`;for(let i=0;i<60;i++){const a=i*Math.PI/30,l=i%5?6:13;s+=`<line x1="${cx+Math.sin(a)*(R-3)}" y1="${cy-Math.cos(a)*(R-3)}" x2="${cx+Math.sin(a)*(R-3-l)}" y2="${cy-Math.cos(a)*(R-3-l)}" stroke="var(--ink)" stroke-width="${i%5?1.3:2.6}"/>`}for(let i=1;i<=12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*108}" y="${cy-Math.cos(a)*108}" font-size="30" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle" dominant-baseline="central">${i}</text>`}for(let i=0;i<12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*(R+23)}" y="${cy-Math.cos(a)*(R+23)}" font-size="16" font-family="Andika,sans-serif" font-weight="700" fill="var(--sea)" text-anchor="middle" dominant-baseline="central">${i*5}</text>`}const ha=(h%12+m/60)*Math.PI/6,ma=m*Math.PI/30,hl=66,ml=90;s+=`<line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ha)*hl}" y2="${cy-Math.cos(ha)*hl}" stroke="var(--ink)" stroke-width="11" stroke-linecap="round"/><line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ma)*ml}" y2="${cy-Math.cos(ma)*ml}" stroke="var(--sea)" stroke-width="6" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="8" fill="var(--ink)"/>`;const tag=(ang,r,txt,col)=>{let d=ang*180/Math.PI-90;if(d>90||d<-90)d+=180;const x=cx+Math.sin(ang)*r,y=cy-Math.cos(ang)*r;return`<text transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${d.toFixed(1)})" y="-12" font-size="14" font-weight="700" font-family="Andika,sans-serif" fill="${col}" stroke="var(--surface)" stroke-width="3" paint-order="stroke" text-anchor="middle" dominant-baseline="central">${txt}</text>`};s+=tag(ha,38,"hour hand","var(--ink)")+tag(ma,51,"minute hand","var(--sea)");return s+`</svg>`};function tpsClockHtml(){return F.row([F.clockLab(3,0),"3:00, three o'clock"],[F.clockLab(7,30),"7:30, half past seven"])+`<ul class="frames"><li><b>Short hand = hours.</b> Read the big numbers, 1 to 12.</li><li><b>Long hand = minutes.</b> Read the small numbers around the edge. They count by 5s.</li></ul>`+F.table(["Where the long hand points","Minutes","How to write it and say it"],[["straight up at the 12","0 minutes","3:00, three o'clock"],["straight down at the 6","30 minutes","7:30, seven thirty or half past seven"]])+`<ul class="frames"><li>The short hand is the hour. The long hand is the minutes.</li><li>At half past, the short hand sits between two numbers. Say the smaller number.</li></ul>`}function tpsRulerHtml(){return `<div style="text-align:center"><img alt="An inch ruler from 0 to 6 with a pencil lined up at 0. The tip of the pencil is at 5 inches." src="data:image/webp;base64,${window.TP_IMG1.wp3.inchruler}" style="width:640px;max-width:100%;height:auto"></div>`+F.table(["Rule","Why it matters"],[["Start at the 0 end","the first unit has to begin where the object begins"],["The units touch, with no gaps","a gap makes the count too small"],["The units do not overlap","an overlap makes the count too big"],["Every unit is the same size","units of different sizes cannot be counted together"]])+`<p class="small">Count the spaces between the marks, not the marks themselves. The pencil above ends at the 5, so it is 5 units long.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["sh, ch, th, wh, ck","two letters, one sound","shop, chin, that, when, duck"],["bl, fl, st, sw, cr","two sounds said close together","flag, stop, swim, crab"],["a_e, i_e, o_e, u_e","the e at the end makes the vowel say its name","cave, bike, note, cube"],["ai, ay, ea, ee, oa, ow","a vowel team: two letters, one vowel sound","rain, day, seal, deep, boat, snow"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, corn, fur"],["-s, -ed, -ing","an ending added to a word","jumps, jumped, jumping"]])+`<ul class="frames"><li>Say each sound, then blend them together. /f/ /l/ /a/ /g/ is flag.</li><li>A long vowel says its name. A short vowel does not.</li><li>Clap the parts: snow-flake is two parts.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who it is about and where they are","First, ____."],["2. Next","what happened in the middle","Next, ____."],["3. Last","how it ended and how you felt","Last, ____."]])+`<ul class="frames"><li>Keep the parts in the order they happened.</li><li>Use the names from the story, not he or she on its own.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={nl:{name:"Number line to 20",std:["1.MD.A.2","1.MD.B.3","1.MD.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.MD.A.1"],html:nlHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{nlOn[x.dataset.n]=!nlOn[x.dataset.n];r()})},tf:{name:"Ten frames",std:["1.NBT.B.2","1.NBT.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.NBT.A.1"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},blocks:{name:"Tens and ones blocks",std:["1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","2.NBT.B.5","2.OA.A.1"],html:blkHtml,bind:(b,r)=>b.querySelectorAll("[data-b]").forEach(x=>x.onclick=()=>{if(x.dataset.b==="x")blk=[0,0];else{const i=+x.dataset.b;blk[i]=Math.max(0,Math.min(i?19:9,blk[i]+ +x.dataset.d))}r()})},chart:{name:"120 chart",std:["1.NBT.A.1","1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","1.OA.C.5","2.NBT.A.1","2.NBT.B.5","2.OA.A.1"],html:c120Html,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{c120On[x.dataset.n]=!c120On[x.dataset.n];r()})},sent:{name:"Sentence starters",std:["W.1.1","W.1.2","W.1.3","W.1.8"],html:sentHtml},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["1.MD.A.2","2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.1.2","RF.1.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.1.1","SL.1.4","W.1.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.1.1","RI.1.1","RL.1.1","SL.1.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.1.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"nl",std:["1.OA.C.5"],msg:"1.OA.C.5 is about counting on and back. With the number line, this stop shows the student can do it with a visual, not in their head."},{t:"sent",msg:"Sentence starters supply the opening, the time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"blocks",std:["1.NBT.C.6"],msg:"Building and removing tens on the block mat makes the subtraction a model the student moved rather than a fact worked out. Note it."},{t:"nl",std:["1.OA.B.3"],msg:"If the number line was used to recount 9 + 4, that is counting, not using the order of the addends. Note what the student did."},{t:"clock",std:["1.MD.B.3","2.MD.C.7"],msg:"The clock card names which hand is the hour and what each long hand position is worth, so a time read with it open is supported, not independent."},{t:"ruler",std:["1.MD.A.2","2.MD.A.1"],msg:"The ruler card shows the units already laid end to end from 0 and states the no gaps rule, so count a length found with it open as supported, not independent."},{t:"letters",std:["RF.1.3"],msg:"The letter and sound card lists the patterns and an example word for each, so a word sounded out with it open is supported, not independent."},{t:"letters",std:["RF.1.2"],msg:"RF.1.2 is listening only. If the card was open, note that the student had the blending and long vowel rules in front of them."},{t:"retell",std:["RL.1.1","SL.1.4","W.1.3"],msg:"The card gives the order words first, next and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.1.1","RI.1.1","SL.1.2","L.1.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.1.4"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
